item.aggregated_output:
                        f"row {row_number} has {len(fields)} fields; expected {len(headers)}"
                    )
                rows.append((row_number, dict(zip(headers, fields))))
            return headers, rows
    except OSError as exc:
        raise UserError(f"cannot read input CSV {path!r}: {exc}") from exc
    except csv.Error as exc:
        raise UserError(f"malformed CSV: {exc}") from exc
    except UnicodeDecodeError as exc:
        raise UserError(f"input CSV is not valid UTF-8: {exc}") from exc


def require_columns(headers: Iterable[str], columns: Iterable[str]) -> None:
    known = set(headers)
    for column in columns:
        if column not in known:
            raise UserError(f"unknown column: {column!r}")


def parse_filters(raw_filters: list[str], headers: list[str]) -> list[tuple[str, str]]:
    filters: list[tuple[str, str]] = []
    for expression in raw_filters:
        if "=" not in expression:
            raise UserError(f"malformed filter {expression!r}; expected COLUMN=VALUE")
        column, value = expression.split("=", 1)
        if not column:
            raise UserError(f"malformed filter {expression!r}; column name cannot be empty")
        require_columns(headers, [column])
        filters.append((column, value))
    return filters


def decimal_cell(value: str, row_number: int, column: str) -> Decimal:
    if not value.strip():
        raise UserError(f"blank numeric value at row {row_number}, column {column!r}")
    try:
        number = Decimal(value)
    except InvalidOperation as exc:
        raise UserError(f"invalid numeric value {value!r} at row {row_number}, column {column!r}") from exc
    if not number.is_finite():
        raise UserError(f"invalid numeric value {value!r} at row {row_number}, column {column!r}")
    return number


def decimal_text(value: Decimal) -> str:
    """Return non-exponential decimal text without insignificant trailing zeroes."""
    if value == 0:
        return "0"
    return format(value.normalize(), "f")


def aggregate(
    rows: list[tuple[int, dict[str, str]]], group_by: str, sum_columns: list[str], avg_columns: list[str]
) -> list[dict[str, str]]:
    # Mapping values are [sum, count] so each input value is parsed exactly once.
    groups: OrderedDict[str, dict[str, list[Decimal | int]]] = OrderedDict()
    numeric_columns = list(dict.fromkeys(sum_columns + avg_columns))
    for row_number, row in rows:
        group = row[group_by]
        measures = groups.setdefault(group, {})
        for column in numeric_columns:
            value = decimal_cell(row[column], row_number, column)
            if column not in measures:
                measures[column] = [Decimal(0), 0]
            measures[column][0] += value
            measures[column][1] += 1

    result: list[dict[str, str]] = []
    for group, measures in sorted(groups.items()):
        item: dict[str, str] = {group_by: group}
        for column in sum_columns:
            item[f"sum_{column}"] = decimal_text(measures[column][0])
        for column in avg_columns:
            total, count = measures[column]
            item[f"avg_{column}"] = decimal_text(total / count)
        result.append(item)
    return result


def write_output(rows: list[dict[str, str]], headers: list[str], output_format: str) -> None:
    if output_format == "json":
        json.dump(rows, sys.stdout, ensure_ascii=False, separators=(",", ":"))
        sys.stdout.write("\n")
        return

    writer = csv.DictWriter(sys.stdout, fieldnames=headers, lineterminator="\r\n", extrasaction="raise")
    writer.writeheader()
    writer.writerows(rows)


def run(argv: list[str]) -> None:
    args = parse_arguments(argv)
    headers, rows = read_csv(args.input)
    filters = parse_filters(args.where, headers)
    require_columns(headers, [column for column, _ in filters])
    require_columns(headers, args.sum_columns + args.avg_columns)
    if args.sum_columns or args.avg_columns:
        if not args.group_by:
            raise UserError("--sum and --avg require --group-by")
        require_columns(headers, [args.group_by])
    elif args.group_by:
        require_columns(headers, [args.group_by])

    filtered = [(number, row) for number, row in rows if all(row[column] == value for column, value in filters)]
    if args.sum_columns or args.avg_columns:
        output_rows = aggregate(filtered, args.group_by, args.sum_columns, args.avg_columns)
        output_headers = [args.group_by]
        output_headers += [f"sum_{column}" for column in args.sum_columns]
        output_headers += [f"avg_{column}" for column in args.avg_columns]
    else:
        output_rows = [row for _, row in filtered]
        output_headers = headers
    write_output(output_rows, output_headers, args.output)


def main() -> int:
    try:
        run(sys.argv[1:])
    except UserError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    return 0


